@PluginDescriptor(name="Lead the Way", description="Step-by-step destination directions", tags={"travel","route"})
public class LeadTheWayPlugin extends Plugin {
    @Inject private LeadTheWayConfig config;
    @Inject private ConfigManager configManager;
    private volatile boolean showBanner;
    boolean canvasHelperEnabled() { return showBanner; }
    void setCanvasHelperEnabled(boolean enabled) {
        configManager.setConfiguration("leadtheway", "showCanvasHelper", enabled);
    }

    @Provides LeadTheWayConfig provideConfig(ConfigManager manager) {
        return manager.getConfig(LeadTheWayConfig.class);
    }

    @Subscribe public void onConfigChanged(ConfigChanged event) {
        if ("leadtheway".equals(event.getGroup()) && "showCanvasHelper".equals(event.getKey())) {
            showBanner = config.showCanvasHelper();
        }
    }

    @Inject private Client client;
    @Inject private ClientToolbar toolbar;
    @Inject private net.runelite.client.game.SpriteManager sprites;
    @Inject private OverlayManager overlays;
    @Inject private WorldMapPointManager mapPoints;
    private WorldMapPoint marker;
    private MiniGuide miniGuide;
    private NavigationButton nav;
    private GuidePanel panel;
    private SceneGuide overlay;
    private InstructionBanner banner;
    // Identity distinguishes two visits to the same route, including queued Swing updates.
    static final class View {
        final Route route;
        final boolean active;
        volatile Route.Step target;
        View(Route route, boolean active) {
            this.route = route;
            this.active = active;
        }
    }
    private volatile View view;
    private View renderedView;
    private Route.Step renderedStep;
    private boolean suppliesDirty;
    private boolean bankOpen;
    private boolean showingBankPlan;
    private java.util.List<String> previousUpcoming = java.util.List.of();
    private String previousText;
    private static final WorldPoint PAD = Route.point("2490 10162 0");
    private static final WorldPoint OTHER = Route.point("2490 10164 0");
    private static final WorldPoint ENTRANCE = Route.point("1911 4367 0");
    private static final Route.Step STAND_NORTH = new Route.Step(OTHER, "Stand on the northern pressure pad.");
    private static final Route.Step STAND_SOUTH = new Route.Step(PAD, "Stand on the southern pressure pad.");
    private static final Route.Step OPEN = new Route.Step(Route.point("2491 10163 0"), "Open the pressure door beside you.");
    private static final Route.Step ARRIVED = new Route.Step(ENTRANCE, "Arrived at the Kings’ entrance.");

    private synchronized void mark(View owner, Route.Step step) {
        if (owner != view) return;
        if (marker != null) {
            mapPoints.remove(marker);
            marker = null;
        }
        if (step == null || step.target == null) return;
        marker = new WorldMapPoint(step.target, nav.getIcon());
        marker.setName(owner.route.name);
        marker.setTooltip(step.text);
        marker.setSnapToEdge(true);
        marker.setJumpOnClick(true);
        mapPoints.add(marker);
    }

    synchronized void select(Route route, boolean active) {
        mark(view, null);
        view = route == null ? null : new View(route, active);
    }

    @Override protected void startUp() {
        showBanner = config.showCanvasHelper();
        panel = new GuidePanel(this);
        panel.loadPortraits(sprites);
        nav = NavigationButton.builder().tooltip("Lead the Way")
            .icon(net.runelite.client.util.ImageUtil.loadImageResource(getClass(), "/brand/sign-16.png"))
            .panel(panel).build();
        toolbar.addNavigation(nav); overlay = new SceneGuide(); overlays.add(overlay);
        banner = new InstructionBanner();
        overlays.add(banner);
        miniGuide = new MiniGuide(); overlays.add(miniGuide);
    }
    @Override protected void shutDown() {
        toolbar.removeNavigation(nav); overlays.remove(overlay); overlays.remove(banner); overlays.remove(miniGuide); select(null, false); renderedView = null;
    }
    private String supplies(View current, WorldPoint location) {
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (inventory == null) return "Waiting for inventory…";
        if (current.route == Route.HILL_GIANTS) {
            Route.Step stage = current.route.at(location);
            boolean carried = inventory.count(ItemID.EDGEVILLEDUNGEONKEY) > 0;
            ItemContainer bank = bankOpen ? client.getItemContainer(InventoryID.BANK) : null;
            if (bankOpen && bank == null) return "Loading bank…";
            boolean shed = stage == current.route.start && HillGiants.useShed(location,
                carried || bank != null && bank.count(ItemID.EDGEVILLEDUNGEONKEY) > 0);
            String title = stage != current.route.start ? "Continue through the dungeon"
                : shed ? "Cooks’ Guild shed" : "Edgeville trapdoor · No key needed";
            java.util.Map<String,String> rows = shed ? java.util.Map.of(HillGiants.KEY, carried ? "Packed" : "Withdraw 1")
                : java.util.Map.of();
            java.util.List<String> upcoming = HillGiants.list(stage != current.route.start ? current.route.upcoming(stage, java.util.List.of(), true)
                : shed ? java.util.List.of("Climb down in the shed", "Enter the giant chamber")
                : HillGiants.trapdoorSteps(), carried);
            boolean showBank = bankOpen;
            previousText = null;
            SwingUtilities.invokeLater(() -> {
                if (view == current) {
                    if (showBank) panel.showPacking(title, rows);
                    else panel.showDetail(shed ? "Use your brass key at the shed." : stage == current.route.start
                        ? "Edgeville trapdoor · No key needed" : title, false);
                    panel.setUpcoming(upcoming);
                }
            });
            return null;
        }
        if (bankOpen && current.route == Route.KINGS) {
            ItemContainer bank = client.getItemContainer(InventoryID.BANK);
            if (bank == null) return "Loading bank…";
            KingsPacking packing = new KingsPacking(id -> inventory.count(id) + (equipment == null ? 0 : equipment.count(id)), bank::count)
                .plan(location, client.getVarbitValue(VarbitID.FAIRYRING_USE) > 0,
                    client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) > 0,
                    Quest.LUNAR_DIPLOMACY.getState(client) == QuestState.FINISHED,
                    Quest.THE_FREMENNIK_TRIALS.getState(client) == QuestState.FINISHED);
            previousText = null;
            String title = packing.title();
            java.util.List<String> upcoming = packing.upcoming;
            java.util.Map<String,String> rows = packing.items();
            SwingUtilities.invokeLater(() -> { if (view == current) { panel.showPacking(title, rows); panel.setUpcoming(upcoming); } });
            return null;
        }
        StringBuilder status = new StringBuilder("<html><table cellpadding='0' cellspacing='0'>");
        current.route.items.forEach((id, name) -> {
            boolean packed = inventory.contains(id) || equipment != null && equipment.contains(id);
            status.append("<tr><td width='98' height='16'>").append(name).append("</td><td align='right'><font color='").append(packed ? "#a9db83" : "#f2be65")
                .append("'>").append(packed ? "Packed" : "Missing").append("</font></td></tr>");
        });
        return status.append("</table></html>").toString();
    }

    @Subscribe public void onItemContainerChanged(ItemContainerChanged event) {
        if (event.getContainerId() == InventoryID.INVENTORY.getId()
            || event.getContainerId() == InventoryID.BANK.getId() || event.getContainerId() == InventoryID.EQUIPMENT.getId()) {
            suppliesDirty = true;
            gearDirty = true;
        }
    }

    private boolean hillKeyCarried;
    private Route.Step approach;
    private WorldPoint approachLocation;
    private boolean gearDirty = true, wieldedStaff, carriedStaff, hasGlory, hasTablet;

    private Route.Step approach(WorldPoint p, Route.Step fallback) {
        if (!gearDirty && !suppliesDirty && p.equals(approachLocation)) return approach;
        if (gearDirty) {
            ItemContainer worn = client.getItemContainer(InventoryID.EQUIPMENT);
            ItemContainer bag = client.getItemContainer(InventoryID.INVENTORY);
            wieldedStaff = hasStaff(worn);
            carriedStaff = hasStaff(bag);
            hasGlory = java.util.Arrays.stream(KingsPacking.GLORIES).anyMatch(id -> contains(worn, id) || contains(bag, id));
            hasTablet = contains(bag, ItemID.LUNAR_TABLET_WATERBIRTH_TELEPORT);
            gearDirty = false;
        }
        Route.Step candidate = RellekkaApproach.choose(p, client.getVarbitValue(VarbitID.FAIRYRING_USE) > 0,
            wieldedStaff, carriedStaff, client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) > 0,
            hasGlory, hasTablet && Quest.LUNAR_DIPLOMACY.getState(client) == QuestState.FINISHED, fallback);
        if (approach == null || !java.util.Objects.equals(candidate.target, approach.target)
            || !candidate.text.equals(approach.text)) approach = candidate;
        approachLocation = p;
        suppliesDirty = false;
        return approach;
    }

    private static boolean contains(ItemContainer container, int id) {
        return container != null && container.contains(id);
    }

    private static boolean hasStaff(ItemContainer c) {
        return contains(c, ItemID.DRAMEN_STAFF) || contains(c, ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF);
    }

    private boolean rockOnPad(WorldView world, WorldPoint pad) {
        LocalPoint local = LocalPoint.fromWorld(world, pad);
        if (local == null) return false;
        Tile tile = world.getScene().getTiles()[pad.getPlane()][local.getSceneX()][local.getSceneY()];
        if (tile == null) return false;
        java.util.List<TileItem> items = tile.getGroundItems();
        if (items != null) {
            for (TileItem item : items) if (item.getId() == ItemID.VT_USELESS_ROCK) return true;
        }
        return false;
    }

    static Route.Step padInstruction(WorldPoint player, boolean southRock, boolean northRock, Route.Step drop) {
        if (southRock) return player.equals(OTHER) ? OPEN : STAND_NORTH;
        if (northRock) return player.equals(PAD) ? OPEN : STAND_SOUTH;
        return drop;
    }

    private void publish(View current, String text) {
        publish(current, text, java.util.List.of());
    }
    private void publish(View current, String text, java.util.List<String> upcoming) {
        publish(current, text, upcoming, null, null);
    }
    private void publish(View current, String text, java.util.List<String> upcoming, String milestone, String instruction) {
        if (text.equals(previousText) && upcoming.equals(previousUpcoming)) return;
        previousUpcoming = upcoming;
        previousText = text;
        SwingUtilities.invokeLater(() -> {
            if (view == current) {
                panel.showDetail(text, current.active);
                if (milestone == null) panel.setUpcoming(upcoming);
                else panel.showProgress(milestone, instruction, upcoming);
            }
        });
    }

    @Subscribe public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) return;
        renderedView = null;
        View current = view;
        if (current != null) {
            current.target = null;
            mark(current, null);
            previousText = null;
            publish(current, "Waiting for your character…");
        }
    }

    @Subscribe public void onGameTick(GameTick event) {
        View current = view;
        if (current == null) return;
        if (current != renderedView) {
            gearDirty = true;
            renderedView = current;
            renderedStep = null;
            previousText = null;
            suppliesDirty = true;
        }
        Player player = client.getLocalPlayer();
        if (client.getGameState() != GameState.LOGGED_IN || player == null) {
            current.target = null;
            mark(current, null);
            publish(current, "Waiting for your character…");
            return;
        }
        net.runelite.api.widgets.Widget bankWidget = client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.ITEMS);
        boolean open = bankWidget != null && !bankWidget.isHidden();
        if (open != bankOpen) {
            bankOpen = open;
            suppliesDirty = true;
        }
        if (!current.active || bankOpen) {
            showingBankPlan = bankOpen;
            if (suppliesDirty) {
                suppliesDirty = false;
                current.target = null;
            mark(current, null);
                String message = supplies(current, player.getWorldLocation());
                if (message != null) {
                    Route.Step stage = current.route.at(player.getWorldLocation());
                    java.util.List<String> prefix = java.util.List.of();
                    if (current.route == Route.KINGS && stage == current.route.start && !bankOpen) {
                        Route.Step travel = approach(player.getWorldLocation(), stage);
                        java.util.ArrayList<String> approachSteps = new java.util.ArrayList<>();
                        approachSteps.add(travel.text);
                        if (travel != stage) approachSteps.addAll(travel.after);
                        prefix = approachSteps;
                    }
                    publish(current, message, current.route.upcoming(stage, prefix, true));
                }
            }
            return;
        }
        if (showingBankPlan) {
            renderedStep = null;
            showingBankPlan = false;
        }
        WorldPoint location = player.getWorldLocation();
        Route.Step stage = current.route.at(location);
        Route.Step next = stage;
        if (current.route == Route.HILL_GIANTS) {
            if (suppliesDirty) {
                renderedStep = null;
                hillKeyCarried = contains(client.getItemContainer(InventoryID.INVENTORY), ItemID.EDGEVILLEDUNGEONKEY);
                suppliesDirty = false;
            }
            next = stage == current.route.start ? HillGiants.surface(location, hillKeyCarried) : HillGiants.dungeon(stage, hillKeyCarried);
        }
        if (current.route == Route.KINGS && next == current.route.start) next = approach(location, next);
        if (current.route == Route.KINGS && PAD.equals(next.target)) {
            WorldView world = player.getWorldView();
            boolean southRock = rockOnPad(world, PAD);
            next = padInstruction(location, southRock, !southRock && rockOnPad(world, OTHER), next);
        }
        if (current.route == Route.KINGS && location.distanceTo(ENTRANCE) <= 2) next = ARRIVED;
        if (view != current) return;
        current.target = next;
        if (next != renderedStep) {
            renderedStep = next;
            mark(current, next);
            publish(current, "<html><body width='124'>" + next.text + "</body></html>",
                next == ARRIVED ? java.util.List.of()
                    : next == HillGiants.SHED_WALK ? java.util.List.of("Climb down in the shed", "Enter the giant chamber")
                    : next == HillGiants.SHED_DOOR ? java.util.List.of("Enter the giant chamber")
                    : next == HillGiants.PICKUP ? current.route.upcoming(stage, java.util.List.of(), true)
                    : next == HillGiants.EDGEVILLE ? HillGiants.list(HillGiants.trapdoorSteps(), hillKeyCarried)
                    : current.route == Route.HILL_GIANTS ? HillGiants.list(current.route.upcoming(stage, next.after, false), hillKeyCarried)
                    : current.route.upcoming(stage, next.after, false),
                next == HillGiants.PICKUP ? HillGiants.PICKUP_LABEL : current.route.milestone(stage, next), next.text);
        }
    }
    private final class MiniGuide extends Overlay {
        MiniGuide() {
            setPosition(OverlayPosition.DYNAMIC);
            setLayer(OverlayLayer.ABOVE_WIDGETS);
        }

        @Override public Dimension render(Graphics2D g) {
            View active = view;
            Route.Step step = active == null ? null : active.target;
            if (step == null || step.target == null || client.getGameState() != GameState.LOGGED_IN) return null;
            WorldView world = client.getTopLevelWorldView();
            CameraFocusableEntity focus = client.getCameraFocusEntity();
            if (world == null || world.getPlane() != step.target.getPlane() || focus == null) return null;
            LocalPoint center = focus.getCameraFocus();
            if (center == null || center.getWorldView() != WorldView.TOPLEVEL) return null;
            int widgetId = !client.isResized() ? InterfaceID.Toplevel.MINIMAP
                : client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
                    ? InterfaceID.ToplevelPreEoc.MINIMAP : InterfaceID.ToplevelOsrsStretch.MINIMAP;
            Widget widget = client.getWidget(widgetId);
            if (widget == null || widget.isHidden()) return null;
            int radius = Math.min(widget.getWidth(), widget.getHeight()) / 2 - 13;
            double zoom = client.getMinimapZoom();
            if (radius <= 0 || zoom <= 0) return null;
            double dx = (step.target.getX() - world.getBaseX()) * 128.0 + 64 - center.getX();
            double dy = (step.target.getY() - world.getBaseY()) * 128.0 + 64 - center.getY();
            double pixels = Math.hypot(dx, dy) * zoom / 128;
            double scale = pixels > radius ? radius / pixels : 1;
            LocalPoint projected = new LocalPoint(center.getX() + (int)(dx * scale),
                center.getY() + (int)(dy * scale), world);
            net.runelite.api.Point point = Perspective.localToMinimap(client, projected, 32000);
            if (point == null) return null;
            int x = point.getX(), y = point.getY();
            if (pixels <= radius) {
                g.setColor(Color.BLACK); g.fillOval(x-4,y-4,9,9);
                g.setColor(Color.CYAN); g.fillOval(x-3,y-3,7,7);
            } else {
                Rectangle bounds = widget.getBounds();
                double angle = Math.atan2(y-bounds.getCenterY(), x-bounds.getCenterX());
                Graphics2D arrow = (Graphics2D)g.create();
                try {
                    arrow.translate(x,y); arrow.rotate(angle);
                    Polygon shape = new Polygon(new int[]{7,-5,-2,-5},new int[]{0,-5,0,5},4);
                    arrow.setColor(Color.CYAN); arrow.fill(shape);
                    arrow.setColor(Color.BLACK); arrow.draw(shape);
                } finally { arrow.dispose(); }
            }
            return null;
        }
    }

    private static final Color BACKGROUND = new Color(24,24,24,222);
    private final class SceneGuide extends Overlay {
        SceneGuide() { setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.ABOVE_SCENE); }
        public Dimension render(Graphics2D g) {
            View current = view;
            if (current == null || !current.active || client.getGameState() != GameState.LOGGED_IN) return null;
            Route.Step s = current.target;
            if (s == null) return null;
            WorldView world = client.getTopLevelWorldView();
            if (world == null) return null;
            LocalPoint l=s.target == null ? null : LocalPoint.fromWorld(world,s.target);
            if(l!=null) {
                Polygon tile=Perspective.getCanvasTilePoly(client,l);
                if(tile!=null) OverlayUtil.renderPolygon(g,tile,Color.CYAN);
            }
            return null;
        }
    }

    private final class InstructionBanner extends Overlay {
        InstructionBanner() {
            setPosition(OverlayPosition.TOP_LEFT);
            setLayer(OverlayLayer.ABOVE_WIDGETS);
        }

        @Override public String getName() { return "Lead the Way instruction"; }

        @Override public Dimension render(Graphics2D g) {
            View current = view;
            if (current == null || !current.active || client.getGameState() != GameState.LOGGED_IN) return null;
            if (!showBanner) return null;
            Route.Step instruction = current.target;
            if (instruction == null) return null;

            FontMetrics font = g.getFontMetrics();
            int width = font.stringWidth(instruction.text) + 18;
            int height = font.getHeight() + 10;
            g.setColor(BACKGROUND);
            g.fillRect(0, 0, width, height);
            g.setColor(Color.WHITE);
            g.drawString(instruction.text, 9, 5 + font.getAscent());
            return new Dimension(width, height);
        }
    }
}

package com.lumbylabs.routes;

import net.runelite.api.coords.WorldPoint;

/** Approach choices for the Waterbirth ferry. All coordinates are on the surface. */
final class RellekkaApproach {
    private static final WorldPoint DOCK = Route.point("2620 3686 0");
    private static final WorldPoint DKS = Route.point("2744 3719 0");
    private static final WorldPoint EDGE = Route.point("3129 3496 0");
    private static final WorldPoint[] RINGS = {
        Route.point("2900 3111 0"), EDGE, Route.point("2700 3247 0"),
        Route.point("2412 4434 0"), Route.point("2644 3495 0")
    };
    static final String FERRY = "Sail with Jarvald", RING = "Use fairy ring DKS";
    enum Travel {
        WALK(FERRY), TABLET("Teleport to Waterbirth"), RING(RellekkaApproach.RING, FERRY), GLORY("Teleport to Edgeville", RellekkaApproach.RING, FERRY);
        final java.util.List<String> steps;
        Travel(String... steps) { this.steps = java.util.List.of(steps); }
    }
    static Travel travel(WorldPoint p, boolean ringReady, boolean glory, boolean tablet) {
        if (p.distanceTo(DOCK) <= 60 || (p.distanceTo(DKS) <= 95 && p.getX() <= DKS.getX()+16)) return Travel.WALK;
        if (tablet) return Travel.TABLET;
        if (ringReady) {
            for (WorldPoint ring : RINGS) if (p.distanceTo(ring) <= 24) return Travel.RING;
            if (p.distanceTo(EDGE) <= 70) return Travel.RING;
            if (glory && p.getPlane() == 0 && p.getY() < 3520) return Travel.GLORY;
        }
        return Travel.WALK;
    }
    static Route.Step choose(WorldPoint p, boolean ringAccess, boolean wielded, boolean carried,
                             boolean diary, boolean glory, boolean tablet, Route.Step fallback) {
        switch (travel(p, ringAccess && (wielded || carried || diary), glory, tablet)) {
            case TABLET:
                return new Route.Step(null, "Break your Waterbirth teleport tablet to reach the island.");
            case GLORY:
                return new Route.Step(null, "Use your glory to reach Edgeville for the DKR fairy ring.", RING, FERRY);
            case RING:
                for (WorldPoint ring : RINGS) {
                    if (p.distanceTo(ring) <= 24) return new Route.Step(ring, !wielded && !diary
                        ? "Equip your staff, then configure the marked fairy ring to DKS."
                        : "Configure the marked fairy ring to DKS (Polar Hunter area).", FERRY);
                }
                return new Route.Step(EDGE, "Walk to fairy ring DKR, east of the river near Edgeville.", RING, FERRY);
            default:
                if (p.distanceTo(DOCK) <= 10) return new Route.Step(DOCK, "Speak to Jarvald and sail to Waterbirth Island.");
                if (p.distanceTo(DOCK) <= 60) return new Route.Step(DOCK, "Head to the western docks and find Jarvald.", FERRY);
                if (p.distanceTo(DKS) <= 95 && p.getX() <= DKS.getX()+16)
                    return new Route.Step(DOCK, "Head west into Rellekka, then to Jarvald at the western docks.", FERRY);
                return fallback;
        }
    }
}

package com.lumbylabs.routes;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID.IconBoss25x25;

final class Route {
    static final class Step {
        final WorldPoint target;
        final String text;
        final List<String> after;
        Step(WorldPoint target, String text, String... after) {
            this.target = target; this.text = text; this.after = List.of(after);
        }
    }
    static final class Stage {
        final WorldPoint a, b;
        final String milestone;
        final Step next;
        Stage(String line) {
            String[] fields = line.split("[|]", -1);
            milestone = fields.length > 4 ? fields[4] : fields[3];
            a = point(fields[0]); b = point(fields[1]);
            next = new Step(point(fields[2]), fields[3]);
        }
        boolean contains(WorldPoint p) {
            return p.getPlane() == a.getPlane()
                && between(p.getX(), a.getX(), b.getX()) && between(p.getY(), a.getY(), b.getY());
        }
        private boolean between(int n, int a, int b) { return n >= Math.min(a,b) && n <= Math.max(a,b); }
    }
    final String name, aliases;
    enum Length {
        SHORT("Short"), MEDIUM("Medium"), LONG("Long"), VERY_LONG("Very long");
        final String label;
        Length(String label) { this.label = label; }
    }
    final Length length;
    final boolean members;
    final int minimumAgility;
    final int[] portraits;
    final Map<Integer,String> items;
    final List<Stage> stages = new ArrayList<>();
    final Step start;
    Route(String name, String aliases, Map<Integer,String> items, Step start, String resource, boolean members, int minimumAgility, Length length, int... portraits) {
        this.portraits = portraits.clone();
        this.members = members;
        this.length = length;
        this.minimumAgility = minimumAgility;
        this.name = name; this.aliases = aliases; this.items = items; this.start = start;
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                Objects.requireNonNull(Route.class.getResourceAsStream(resource)), StandardCharsets.UTF_8))) {
            reader.lines().forEach(line -> stages.add(new Stage(line)));
        } catch (IOException e) { throw new UncheckedIOException(e); }
    }
    static WorldPoint point(String value) {
        String[] n = value.split(" ");
        return new WorldPoint(Integer.parseInt(n[0]), Integer.parseInt(n[1]), Integer.parseInt(n[2]));
    }
    Step at(WorldPoint p) {
        for (Stage stage : stages) { if (stage.contains(p)) return stage.next; }
        return start;
    }
    String milestone(Step stage, Step active) {
        if (active == HillGiants.EDGEVILLE) return "Climb down the trapdoor";
        if (active == HillGiants.SHED_DOOR) return "Climb down in the shed";
        for (Stage entry : stages) {
            if (entry.next == stage && !entry.milestone.isEmpty()) return entry.milestone;
        }
        return active.text;
    }
    List<String> upcoming(Step stage, List<String> approach, boolean includeCurrent) {
        List<String> result = new ArrayList<>(approach);
        boolean started = stage == start;
        String previous = "";
        for (Stage entry : stages) {
            if (entry.next == stage) {
                started = true;
                if (!includeCurrent) previous = entry.milestone;
            }
            if (started && !entry.milestone.isEmpty() && !entry.milestone.equals(previous)) {
                result.add(entry.milestone);
                previous = entry.milestone;
            }
        }
        return List.copyOf(result);
    }
    static final Route KINGS = new Route("Dagannoth Kings", "dks dag kings dagg kings rex prime supreme waterbirth",
        Map.of(ItemID.VT_USELESS_ROCK,"Pet rock",ItemID.RUNE_THROWNAXE,"Rune thrownaxe"),
        new Step(point("2620 3686 0"),"Travel to Rellekka docks and sail with Jarvald.", RellekkaApproach.FERRY), "/kings.route", true, 0, Length.VERY_LONG,
        IconBoss25x25.DAGANNOTH_REX, IconBoss25x25.DAGANNOTH_PRIME, IconBoss25x25.DAGANNOTH_SUPREME);
    static final Route HILL_GIANTS = new Route("Hill Giants", "edgeville dungeon brass key giants f2p",
        Map.of(), HillGiants.EDGEVILLE, "/hill-giants.route", false, 0, Length.MEDIUM);
    static final List<Route> CATALOG = List.of(KINGS, HILL_GIANTS);
}

package com.lumbylabs.routes;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.LinkedHashMap;
import javax.imageio.ImageIO;
import javax.swing.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BankLayoutTest {
    private static Component find(Container parent, String text) {
        for (Component c : parent.getComponents()) {
            if (c instanceof AbstractButton && text.equals(((AbstractButton)c).getActionCommand())) return c;
            if (c instanceof JLabel && (text.equals(((JLabel)c).getText()) || text.equals(((JLabel)c).getAccessibleContext().getAccessibleName()))) return c;
            if (c instanceof Container) {
                Component match = find((Container)c, text);
                if (match != null) return match;
            }
        }
        return null;
    }
    private static void layout(Container c) {
        c.doLayout();
        for (Component child : c.getComponents()) if (child instanceof Container) layout((Container)child);
    }
    @Test public void currentStepMovesBetweenSeparateCards() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            GuidePanel panel = new GuidePanel(new LeadTheWayPlugin());
            ((JButton)find(panel,"Hill Giants")).doClick(0);
            panel.showProgress("Trapdoor", "Open the trapdoor.", java.util.List.of("North passage", "Chamber"));
            Container previous = find(panel,"Current · Step 1 of 3").getParent();
            assertNotSame(previous, find(panel,"Step 2 of 3").getParent());
            panel.showProgress("North passage", "Head north.", java.util.List.of("Chamber"));
            assertNotNull(find(panel,"Done · Step 1 of 3"));
            assertNotNull(find(panel,"Current · Step 2 of 3"));
            assertNotNull(find(panel,"Step 3 of 3"));
        });
    }
    @Test public void routeGuideFitsOnNarrowSidebar() throws Exception {
        GuidePanel[] holder = new GuidePanel[1];
        SwingUtilities.invokeAndWait(() -> {
            GuidePanel p = new GuidePanel(new LeadTheWayPlugin());
            holder[0] = p;
            ((JButton)find(p,"Hill Giants")).doClick(0);
            ((JButton)find(p,"Guide me")).doClick(0);
            p.showProgress("Climb down the trapdoor", "Open the trapdoor in the ruins south of Edgeville bank.",
                java.util.List.of("Follow the north passage", "Follow the east corridor", "Round the eastern bend"));
            p.setSize(225,540);
            layout(p);
        });
        SwingUtilities.invokeAndWait(() -> {
            GuidePanel p = holder[0];
            layout(p);
            assertNotNull(find(p,"Current · Step 1 of 4"));
            if (Boolean.getBoolean("routes.preview")) {
                BufferedImage img = new BufferedImage(225,540,BufferedImage.TYPE_INT_RGB);
                Graphics2D g = img.createGraphics(); p.printAll(g); g.dispose();
                try { ImageIO.write(img,"png",new File("build/hill-guide.png")); }
                catch(java.io.IOException e) { throw new AssertionError(e); }
            }
        });
    }
    @Test public void ferryChecklistFitsAtTwoSidebarWidths() throws Exception {
        GuidePanel[] holder = new GuidePanel[1];
        SwingUtilities.invokeAndWait(() -> {
            GuidePanel p = new GuidePanel(new LeadTheWayPlugin());
            holder[0] = p;
            ((JButton)find(p,"Dagannoth Kings")).doClick(0);
            ((JButton)find(p,"Guide me")).doClick(0);
            LinkedHashMap<String,String> rows = new LinkedHashMap<>();
            rows.put("Ferry coins","Withdraw 1,000");
            rows.put("Pet rock","Missing"); rows.put("Rune thrownaxe","Missing");
            p.showPacking("Rellekka ferry",rows);
        });
        for (int width : new int[]{225,170}) {
            SwingUtilities.invokeAndWait(() -> { holder[0].setSize(width,420); layout(holder[0]); });
            SwingUtilities.invokeAndWait(() -> {
                GuidePanel p = holder[0]; layout(p);
                for(String value : new String[]{"Bank checklist","Rune thrownaxe","Withdraw 1,000","End route"}) {
                    Component c = find(p,value);
                    assertNotNull(value,c);
                    assertTrue(value,c.getWidth() >= c.getPreferredSize().width || c instanceof JButton || value.equals("Bank checklist"));
                    Rectangle bounds = SwingUtilities.convertRectangle(c.getParent(),c.getBounds(),p);
                    assertTrue(value,bounds.x >= 0 && bounds.x + bounds.width <= width);
                }
                if (Boolean.getBoolean("routes.preview")) {
                    BufferedImage img = new BufferedImage(width,420,BufferedImage.TYPE_INT_RGB);
                    Graphics2D g = img.createGraphics(); p.printAll(g); g.dispose();
                    try { ImageIO.write(img,"png",new File("build/bank-"+width+".png")); }
                    catch(java.io.IOException e) {throw new AssertionError(e);}
                }
            });
        }
    }
}

package com.lumbylabs.routes;

import java.lang.reflect.Field;
import javax.swing.SwingUtilities;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import org.junit.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class GuideLifecycleTest {
    private final Client client = mock(Client.class);
    private final LeadTheWayPlugin plugin = new LeadTheWayPlugin();
    private GuidePanel panel;

    @Before public void setup() throws Exception {
        inject("client", client);
        inject("mapPoints", mock(net.runelite.client.ui.overlay.worldmap.WorldMapPointManager.class));
        inject("nav", net.runelite.client.ui.NavigationButton.builder().tooltip("Guide").icon(
            new java.awt.image.BufferedImage(16,16,java.awt.image.BufferedImage.TYPE_INT_ARGB)).build());
        SwingUtilities.invokeAndWait(() -> panel = new GuidePanel(plugin));
        inject("panel", panel);
        Player player = mock(Player.class);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getLocalPlayer()).thenReturn(player);
        when(player.getWorldLocation()).thenReturn(Route.point("2549 3758 0"));
        when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(mock(ItemContainer.class));
        clearInvocations(client);
    }
    @Test public void hillGiantsBankedKeyIsUsableOnlyAfterWithdrawal() throws Exception {
        Player player = client.getLocalPlayer();
        when(player.getWorldLocation()).thenReturn(Route.point("3164 3487 0"));
        net.runelite.api.widgets.Widget widget = mock(net.runelite.api.widgets.Widget.class);
        int bankWidget = net.runelite.api.gameval.InterfaceID.Bankmain.ITEMS;
        when(client.getWidget(bankWidget)).thenReturn(widget);
        ItemContainer bank = mock(ItemContainer.class);
        when(client.getItemContainer(InventoryID.BANK)).thenReturn(bank);
        when(bank.count(net.runelite.api.gameval.ItemID.EDGEVILLEDUNGEONKEY)).thenReturn(1);
        plugin.select(Route.HILL_GIANTS, true);
        ticks(1);
        when(client.getWidget(bankWidget)).thenReturn(null);
        ticks(1);
        assertTrue(panel.detail.getText().contains("trapdoor"));
        ItemContainer bag = client.getItemContainer(InventoryID.INVENTORY);
        when(bag.contains(net.runelite.api.gameval.ItemID.EDGEVILLEDUNGEONKEY)).thenReturn(true);
        plugin.onItemContainerChanged(new net.runelite.api.events.ItemContainerChanged(InventoryID.INVENTORY.getId(), bag));
        ticks(1);
        assertTrue(panel.detail.getText().contains("shed"));
        when(player.getWorldLocation()).thenReturn(Route.point("3094 3491 0"));
        ticks(1);
        assertTrue(panel.detail.getText().contains("trapdoor"));
        when(player.getWorldLocation()).thenReturn(Route.point("3096 9867 0"));
        ticks(1);
        assertTrue(panel.detail.getText().contains("north"));
        when(player.getWorldLocation()).thenReturn(Route.point("3110 9837 0"));
        ticks(1);
        assertTrue(panel.detail.getText().contains("reached"));
    }
    private void inject(String name, Object value) throws Exception {
        Field field = LeadTheWayPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
    private void ticks(int count) throws Exception {
        for (int i = 0; i < count; i++) plugin.onGameTick(new GameTick());
        SwingUtilities.invokeAndWait(() -> {});
    }
    @Test public void idleAndActiveGuideDoNotReadSupplies() throws Exception {
        ticks(100);
        verifyNoInteractions(client);
        plugin.select(Route.KINGS, true);
        ticks(100);
        verify(client, never()).getItemContainer(any(InventoryID.class));
        assertTrue(panel.detail.getText().contains("Enter the cave"));
    }
    @Test public void previewReadsOnceAndQuickReopenRestoresChecklist() throws Exception {
        plugin.select(Route.KINGS, false);
        ticks(100);
        verify(client, times(1)).getItemContainer(InventoryID.INVENTORY);
        SwingUtilities.invokeAndWait(() -> {
            plugin.select(null, false);
            plugin.select(Route.KINGS, false);
            panel.detail.setText("Waiting");
        });
        ticks(1);
        assertTrue(panel.detail.getText().contains("Pet rock"));
    }
    @Test public void staleSwingUpdateCannotReplaceNewView() throws Exception {
        plugin.select(Route.KINGS, false);
        SwingUtilities.invokeAndWait(() -> {
            plugin.onGameTick(new GameTick()); // Queue the old preview callback behind this event.
            plugin.select(null, false);
            plugin.select(Route.KINGS, false);
            panel.detail.setText("Fresh preview");
        });
        SwingUtilities.invokeAndWait(() -> assertEquals("Fresh preview", panel.detail.getText()));
        ticks(1);
        assertTrue(panel.detail.getText().contains("Pet rock"));
    }
    @Test public void inventoryChangesRefreshPreviewAndLogoutClearsOldDirections() throws Exception {
        plugin.select(Route.KINGS, false);
        ticks(1);
        net.runelite.api.events.ItemContainerChanged change =
            new net.runelite.api.events.ItemContainerChanged(InventoryID.EQUIPMENT.getId(), mock(ItemContainer.class));
        plugin.onItemContainerChanged(change);
        ticks(1);
        verify(client, times(2)).getItemContainer(InventoryID.INVENTORY);
        plugin.select(Route.KINGS, true);
        ticks(1);
        net.runelite.api.events.GameStateChanged logout = new net.runelite.api.events.GameStateChanged();
        logout.setGameState(GameState.LOGIN_SCREEN);
        plugin.onGameStateChanged(logout);
        SwingUtilities.invokeAndWait(() -> assertTrue(panel.detail.getText().contains("Waiting")));
        ticks(1);
        assertTrue(panel.detail.getText().contains("Enter the cave"));
    }
    @Test public void rockOnEitherPadGuidesPlayerToOppositePadThenDoor() {
        WorldPoint south = Route.point("2490 10162 0"), north = Route.point("2490 10164 0");
        Route.Step drop = Route.KINGS.at(south);
        assertSame(drop, LeadTheWayPlugin.padInstruction(south,false,false,drop));
        assertEquals(north, LeadTheWayPlugin.padInstruction(south,true,false,drop).target);
        assertEquals(south, LeadTheWayPlugin.padInstruction(north,false,true,drop).target);
        assertTrue(LeadTheWayPlugin.padInstruction(north,true,false,drop).text.contains("Open"));
        assertTrue(LeadTheWayPlugin.padInstruction(south,false,true,drop).text.contains("Open"));
    }
}

package com.lumbylabs.routes;

import java.util.Map;
import static net.runelite.api.gameval.ItemID.*;
import static org.junit.Assert.*;
